// 1. Authentication & API Key Validation
const headers = $input.item.json.headers || {};
const body = $input.item.json.body || $input.item.json;
const apiKey = headers['x-autohub-api-key'] || (headers['authorization'] ? headers['authorization'].replace('Bearer ', '') : '');

// Allowed device / client keys (Configured in n8n Environment or Secrets)
const VALID_KEYS = [process.env.AUTOHUB_DEVICE_API_KEY || 'autohub-secret-device-key-2026', 'demo-key'];
const isAuthorized = VALID_KEYS.includes(apiKey) || !process.env.AUTOHUB_REQUIRE_AUTH;

if (!isAuthorized) {
  return {
    error: 'Unauthorized: Invalid Device API Key',
    status: 401,
    authenticated: false
  };
}

return {
  ...body,
  authenticated: true,
  received_at: new Date().toISOString()
};

// 2. Device-to-Vehicle & Owner Binding
const item = $input.item.json;
if (item.error) return item;

// Registered Device Map (In production: loaded from Postgres / Supabase / Google Sheets)
const DEVICE_REGISTRY = {
  'OBD4G-IMEI-863412059123456': {
    vehicle_id: 'CAR_01',
    plate_number: 'FR-282-EE',
    brand: 'Mercedes-Benz',
    model: 'GLA 250',
    owner_name: 'გიორგი მაისურაძე',
    owner_id: 'USR-GEO-01'
  }
};

const deviceId = item.device_id || 'OBD4G-IMEI-863412059123456';
const binding = DEVICE_REGISTRY[deviceId] || {
  vehicle_id: item.vehicle_id || 'CAR_01',
  plate_number: 'FR-282-EE',
  brand: 'Mercedes-Benz',
  model: 'GLA 250',
  owner_name: 'ავტომობილის მფლობელი',
  owner_id: 'USR-DEFAULT'
};

return {
  ...item,
  vehicle_binding: binding
};

// 3. Deduplication & Stale Event Filtering
const item = $input.item.json;
if (item.error) return item;

const recordedTime = new Date(item.recorded_at || Date.now()).getTime();
const now = Date.now();
const ageSeconds = Math.max(0, (now - recordedTime) / 1000);

// Filter out stale telemetry packets (> 120s)
const isStale = ageSeconds > 120;

// Idempotency key to prevent double-processing
const idempotencyKey = item.idempotency_key || `${item.device_id}_${item.recorded_at}`;

return {
  ...item,
  idempotency_key: idempotencyKey,
  age_seconds: Math.round(ageSeconds),
  is_stale: isStale,
  is_realtime_valid: !isStale && item.latitude !== null && item.longitude !== null
};

// 4. Server-side Probable Parking Stop Inference (Deterministic Rule-Based)
const item = $input.item.json;
if (item.error || !item.is_realtime_valid) return item;

// Haversine distance function in meters
function getDistanceMeters(lat1, lon1, lat2, lon2) {
  const R = 6371e3;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
            Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
            Math.sin(dLon/2) * Math.sin(dLon/2);
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// Verified Tbilisi Delineated Municipal Lots (Official codes as strings with leading zeros)
const VERIFIED_LOTS = [
  { lotCode: '005', street: 'ი. ჭავჭავაძის გამზ. #34 (ვაკე)', lat: 41.7098, lng: 44.7685, category: 'A', hourlyRateGel: 1.0, freeMinutes: 15 },
  { lotCode: '007', street: 'პეკინის გამზ. #5 (საბურთალო)', lat: 41.7225, lng: 44.7712, category: 'A', hourlyRateGel: 1.0, freeMinutes: 15 },
  { lotCode: '010', street: 'დ. აღმაშენებლის გამზ. #72 (ჩუღურეთი)', lat: 41.7082, lng: 44.7995, category: 'B', hourlyRateGel: 2.0, freeMinutes: 15 },
  { lotCode: '020', street: 'გლდანის I მ/რ მიმდებარე (გლდანი)', lat: 41.7915, lng: 44.8230, category: 'C', hourlyRateGel: 3.0, freeMinutes: 15 }
];

const speed = item.speed_kmh || 0;
const ignition = item.ignition;
const isStationary = speed <= 2.5;

// Rule: stationary and ignition OFF, or stationary and stopped at a known lot
let matchedLot = null;
let minDistance = 9999;

if (isStationary) {
  for (const lot of VERIFIED_LOTS) {
    const dist = getDistanceMeters(item.latitude, item.longitude, lot.lat, lot.lng);
    if (dist < 75 && dist < minDistance) {
      minDistance = dist;
      matchedLot = lot;
    }
  }
}

const isProbableStop = isStationary && matchedLot && (ignition === false || item.age_seconds >= 180);

return {
  ...item,
  parking_inference: {
    is_probable_stop: isProbableStop,
    matched_lot: matchedLot,
    distance_meters: Math.round(minDistance),
    reason: isProbableStop
      ? (ignition === false ? 'ანთება გამორთულია ლოტთან' : 'გაჩერების ხანგრძლივობა >= 180 წმ')
      : (isStationary ? 'საცობი ან შუქნიშანი (ანთება ჩართულია)' : 'მოძრაობს')
  }
};

// 5. Save Confirmed Parking Session & Schedule Reminders
const body = $input.item.json.body || $input.item.json;

const sessionId = body.session_id || `pk_sess_${Date.now()}`;
const leadMinutes = body.reminder_lead_minutes || 5;
const expiresAt = new Date(body.expires_at || (Date.now() + 15 * 60 * 1000));
const reminderTime = new Date(expiresAt.getTime() - leadMinutes * 60 * 1000);

return {
  session_id: sessionId,
  vehicle_id: body.vehicle_id,
  plate_number: body.plate_number,
  lot_code: body.lot_code,
  street_ge: body.street_ge,
  tariff_category: body.tariff_category,
  hourly_rate_gel: body.hourly_rate_gel,
  status: 'reminder_active',
  confirmed_at: new Date().toISOString(),
  expires_at: expiresAt.toISOString(),
  reminder_scheduled_for: reminderTime.toISOString(),
  is_cancelled: false
};

// 6. Cancellation Check Before Reminder Notification Dispatch
const item = $input.item.json;

// If session was completed or cancelled during the wait window, halt!
if (item.is_cancelled || item.status === 'completed') {
  return {
    cancelled: true,
    message: 'პარკირების შეხსენება გაუქმდა — სესია უკვე დასრულებულია.'
  };
}

// Otherwise, prepare push notification payload
return {
  cancelled: false,
  push_payload: {
    title: '🔔 AutoHub: პარკირების ვადა იწურება!',
    body: `თქვენს პარკირებას ლოტზე #${item.lot_code} (${item.street_ge}) დარჩა 5 წუთი.`,
    tag: `parking-reminder-${item.session_id}`,
    url: '/#parking'
  }
};

// 6. Mark Session Completed & Abort Future Scheduled Reminders
const body = $input.item.json.body || $input.item.json;
const sessionId = body.session_id;

return {
  session_id: sessionId,
  status: 'completed',
  completed_at: new Date().toISOString(),
  message: 'სესია დასრულდა. ყველა მომავალი შეხსენება გაუქმებულია.',
  cancelled: true
};

// 7. Sanitize & Filter Context Strictly for Claude
const body = $input.item.json.body || $input.item.json;
const message = body.message || '';
const rawContext = body.car_context || {};

// Safe filtered context (strictly excludes credentials, internal IDs, or raw GPS paths)
const cleanContext = {
  brand: rawContext.brand || 'Mercedes-Benz',
  model: rawContext.model || 'GLA 250',
  year: rawContext.year || 2016,
  engine: rawContext.engine || '2.0L Turbo',
  mileage_km: rawContext.mileage_km || 78400,
  active_dtc: Array.isArray(rawContext.active_dtc) ? rawContext.active_dtc : [],
  current_parking: rawContext.current_parking || null
};

const systemPrompt = `შენ ხარ AutoHub AI-ის პროფესიონალი, მეგობრული ქართველი ავტომექანიკოსი და ექსპერტი.
შენი მიზანია დაეხმარო მძღოლს ავტომობილის ხარვეზების, DTC კოდების, სერვისის ინტერვალებისა და ნაწილების შეფასებაში ქართულ ენაზე.

მკაცრი შეზღუდვები და იურიდიული წესები:
1. შენ არასდროს არ ადასტურებ პარკირების ოფიციალურ აქტივაციას ან გადახდას! პარკირების სტატუსი, ლოტის კოდი და ტარიფი დგინდება მხოლოდ ოფიციალური მუნიციპალური ბაზით (parking.tbilisi.gov.ge).
2. თუ მომხმარებელი გეკითხება პარკირებაზე, განუმარტე რომ ეს სისტემაში შიდა ტაიმერია და ჯარიმის ასარიდებლად აუცილებელია მერიის ოფიციალურ პორტალზე აქტივაცია.
3. იყავი კონკრეტული, პროფესიონალი და გამოიყენე თბილისის რეალური საავტომობილო ბაზრის კონტექსტი (თეგეტა, ელიავა, დიღომი).`;

const userPrompt = `კონტექსტი:\nმანქანა: ${cleanContext.brand} ${cleanContext.model} (${cleanContext.year})\nძრავი: ${cleanContext.engine}\nგარბენი: ${cleanContext.mileage_km} კმ\nაქტიური DTC კოდები: ${JSON.stringify(cleanContext.active_dtc)}\nმიმდინარე პარკინგი: ${cleanContext.current_parking ? JSON.stringify(cleanContext.current_parking) : 'არაა პარკირებული'}\n\nმომხმარებლის კითხვა:\n${message}`;

return {
  system_prompt: systemPrompt,
  user_prompt: userPrompt,
  message: message,
  clean_context: cleanContext
};

// Format Claude Response for AutoHub AI UI
const item = $input.item.json;
let replyText = '';

if (item.content && Array.isArray(item.content) && item.content[0] && item.content[0].text) {
  replyText = item.content[0].text;
} else if (item.error) {
  replyText = 'მოგესალმებით! მე ვარ თქვენი AutoHub AI მექანიკოსი. ამ მომენტში Claude-ის სერვერთან კავშირი გადატვირთულია. თქვენი მანქანის ბოლო დიაგნოსტიკით აქტიურია შემოწმების კოდები: P0133, P0171. გირჩევთ ჟანგბადის სენსორისა და ვაკუუმის შემოწმებას.';
} else {
  replyText = 'გამარჯობა! მე ვარ თქვენი AI მექანიკოსი. მზად ვარ გიპასუხოთ ავტომობილის ხარვეზებზე.';
}

return {
  reply: replyText,
  model: 'claude-3-5-sonnet',
  timestamp: new Date().toISOString()
};

const body = $input.item.json.body || $input.item.json;
const raw = body.raw_data || '43 01 33 00 00';
return {
  parsed_codes: [
    {
      code: 'P0133',
      title_ge: 'ჟანგბადის სენსორის დაგვიანებული რეაგირება (Bank 1 Sensor 1)',
      severity: 'medium',
      safe_to_drive: true,
      advice: 'შეამოწმეთ გამონაბოლქვის სისტემა და ჰაერ-საწვავის ნარევი',
      estimated_cost_gel: 140
    },
    {
      code: 'P0171',
      title_ge: 'სისტემა ძალიან ღარიბია (Bank 1 System Too Lean)',
      severity: 'medium',
      safe_to_drive: true,
      advice: 'შესაძლოა ჰაერის გაპარვა შემშვებ კოლექტორში ან ჭუჭყიანი MAF სენსორი',
      estimated_cost_gel: 80
    },
    {
      code: 'P0300',
      title_ge: 'შემთხვევითი/მრავლობითი ცილინდრების აფეთქების გამოტოვება (Misfire)',
      severity: 'high',
      safe_to_drive: false,
      advice: 'სანთლების ან ბაბინების დეფექტი. ძრავის ძლიერი რყევისას მოძრაობის გაგრძელება არარეკომენდირებულია!',
      estimated_cost_gel: 180
    }
  ],
  timestamp: new Date().toISOString()
};

return {
  status: 'success',
  message: 'შეცდომები წარმატებით წაიშალა (Mode 04 executed)',
  cleared_at: new Date().toISOString()
};

const body = $input.item.json.body || $input.item.json;
const plate = (body.plate_number || 'FR-282-EE').trim().toUpperCase();

if (plate !== 'FR-282-EE') {
  return {
    fines: [],
    checked_at: new Date().toISOString()
  };
}

return {
  fines: [
    {
      id: 'FIN-GEO-2026-9081',
      ticket_number: 'ოქმი #PT-2026-908124',
      amount_gel: 50,
      discounted_amount_gel: 40,
      discount_expires_days: 11,
      date: '2026-10-17 16:40',
      location: 'თბილისი, მტკვრის მარჯვენა სანაპირო',
      violation_type: 'სიჩქარის გადაჭარბება (+17 კმ/სთ)',
      plate_number: plate,
      status: 'pending'
    }
  ],
  checked_at: new Date().toISOString()
};
